  color: var(--text-err);
  font-size: 1.1rem;
}

/* Grid of Buttons */
.button-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  width: 100%;
}

/* Buttons */
.btn {
  border: none;
  border-radius: 12px;
  font-size: 1.4rem;
  font-weight: 600;
  padding: 16px 0;
  cursor: pointer;
  color: #ffffff;
  transition: background-color 0.15s ease, transform 0.05s ease;
  display: flex;
  justify-content: center;
  align-items: center;
  user-select: none;
}

.btn:active {
  transform: scale(0.95);
}

.btn:focus-visible {
  outline: 3px solid var(--focus-outline);
  outline-offset: 2px;
}

/* Button Categories */
.btn-num {
  background-color: var(--btn-num);
}
.btn-num:hover {
  background-color: var(--btn-num-hover);
}
.btn-num:active {
  background-color: var(--btn-num-active);
}

.btn-operator {
  background-color: var(--btn-op);
}
.btn-operator:hover {
  background-color: var(--btn-op-hover);
}
.btn-operator:active {
  background-color: var(--btn-op-active);
}

.btn-control {
  background-color: var(--btn-ctrl);
}
.btn-control:hover {
  background-color: var(--btn-ctrl-hover);
}
.btn-control:active {
  background-color: var(--btn-ctrl-active);
}

.btn-evaluate {
  background-color: var(--btn-eval);
}
.btn-evaluate:hover {
  background-color: var(--btn-eval-hover);
}
.btn-evaluate:active {
  background-color: var(--btn-eval-active);
}

/* Responsive media queries to adjust sizes nicely */
@media (max-width: 480px) {
  .calculator-card {
    padding: 16px;
    border-radius: 16px;
  }

  .btn {
    font-size: 1.25rem;
    padding: 14px 0;
  }

  .expression-line {
    font-size: 1.1rem;
  }

  .result-line {
    font-size: 1.75rem;
  }
}

@media (max-width: 360px) {
  .btn {
    font-size: 1.1rem;
    padding: 12px 0;
  }

  .button-grid {
    gap: 8px;
  }
}
